#@title Check shard6 / A100 50% / Soup vs StyleID: SKSF-A + full LFW6000
# Upload this ONE file into the new Colab notebook and run it once.
# Select GPU runtime. No training, no weight mixing, no new research modules.
from pathlib import Path
from uuid import uuid4
import base64, hashlib, importlib.metadata, io, json, os, subprocess, sys, zipfile
from google.colab import drive, files

# Optional overrides may be set in a notebook cell BEFORE running this file.
DRIVE_ROOT = Path(globals().get('DRIVE_ROOT', '/content/drive/MyDrive/StyleID_A100_Champion'))
OUTPUT = Path(globals().get('OUTPUT', str(DRIVE_ROOT/'benchmark_3models_full_lfw_v1')))
SKSF_ROOT = globals().get('SKSF_ROOT', None)
LFW_HOME = globals().get('LFW_HOME', None)
LFW_ARCHIVE = globals().get('LFW_ARCHIVE', None)
CHECKPOINT_OVERRIDES = globals().get('CHECKPOINT_OVERRIDES', {})
BATCH_SIZE = int(globals().get('BATCH_SIZE', 32))
PREFLIGHT_ONLY = bool(globals().get('PREFLIGHT_ONLY', False))
if BATCH_SIZE < 1:
    raise ValueError('BATCH_SIZE must be positive')
if not Path('/content/drive/MyDrive').is_dir():
    drive.mount('/content/drive')
if not DRIVE_ROOT.is_dir():
    raise FileNotFoundError('Check DRIVE_ROOT: '+str(DRIVE_ROOT))

# Keep Colab's installed torch/torchvision; do not replace the GPU runtime.
try:
    installed = importlib.metadata.version('transformers')
except importlib.metadata.PackageNotFoundError:
    installed = None
if installed != '4.52.0' and 'transformers' in sys.modules:
    raise RuntimeError('Transformers already imported at a different version. Restart the new Colab session, then run this file first.')
subprocess.check_call([sys.executable,'-m','pip','install','-q','transformers==4.52.0','scikit-learn','Pillow'])
os.environ['HF_HOME'] = str(DRIVE_ROOT/'hf_cache')
payload = base64.b64decode('')
if hashlib.sha256(payload).hexdigest() != 'e83d985a1251dd5ea724bbfa5ceddfca2bebe2182da695308462b2149c85e5aa':
    raise RuntimeError('Corrupted code bundle')
WORK = Path('/content')/('styleid_full_lfw_code_'+uuid4().hex[:8])
WORK.mkdir(exist_ok=False)
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    expected = json.loads(archive.read('SOURCE_HASHES.json'))
    if set(archive.namelist()) != set(expected)|{'SOURCE_HASHES.json'}:
        raise RuntimeError('Unexpected bundle contents')
    for name,digest in expected.items():
        path = (WORK/name).resolve()
        if not path.is_relative_to(WORK.resolve()):
            raise RuntimeError('Unsafe code path')
        content = archive.read(name)
        if hashlib.sha256(content).hexdigest() != digest:
            raise RuntimeError('Code checksum mismatch: '+name)
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(content)
config = dict(drive_root=str(DRIVE_ROOT),output=str(OUTPUT),local_cache='/content/styleid_full_lfw_cache_v1',
              batch_size=BATCH_SIZE,checkpoints=CHECKPOINT_OVERRIDES,
              sksf_root=str(SKSF_ROOT) if SKSF_ROOT else None,
              lfw_home=str(LFW_HOME) if LFW_HOME else None,
              lfw_archive=str(LFW_ARCHIVE) if LFW_ARCHIVE else None)
config_path = WORK/'runtime_config.json'
config_path.write_text(json.dumps(config,indent=2),encoding='utf-8')
OUTPUT.mkdir(parents=True,exist_ok=True)
(OUTPUT/'PAPER_PROTOCOL.md').write_bytes((WORK/'PAPER_PROTOCOL.md').read_bytes())
command = [sys.executable,'-u','-m','research_v2.lfw_full_compare','--config',str(config_path),'--device','cuda']
if PREFLIGHT_ONLY:
    command += ['--preflight']
print('Drive:',DRIVE_ROOT)
print('Results/cache:',OUTPUT)
print('LFW: fixed View2 full6000; native-funneled RGB -> CLIP processor. Exact Table9 preprocessing was not disclosed.')
log_path = OUTPUT/'run.log'
with log_path.open('a',encoding='utf-8') as log:
    process = subprocess.Popen(command,cwd=WORK,env=dict(os.environ,PYTHONUTF8='1',PYTHONUNBUFFERED='1'),
                               stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',bufsize=1)
    for line in process.stdout:
        print(line,end='',flush=True)
        log.write(line)
        log.flush()
    returncode = process.wait()
if returncode:
    raise RuntimeError('Stopped without changing inputs/model/protocol. See '+str(log_path))
if PREFLIGHT_ONLY:
    print('Preflight OK. Set PREFLIGHT_ONLY=False to evaluate. No model was loaded.')
else:
    result_zip = OUTPUT/'RESULTS_3MODELS_LFW6000.zip'
    print('DONE. Download results:',result_zip)
    files.download(str(result_zip))
